// 2D1B:1DF4: uint16 Roll2D6_1DF4(void)
uint16 Roll2D6_1DF4(void)
{
	uint16 firstDie;
	uint16 secondDie;

	do
		firstDie = (uint16) (byte) GeneratePseudoRandomByte() & 0x07;
	while (firstDie == 0x00 || firstDie > 0x06);

	do
		secondDie = (uint16) (byte) GeneratePseudoRandomByte() & 0x07;
	while (secondDie == 0x00 || secondDie > 0x06);

	return firstDie + secondDie;
}

